local function close(a,b) return math.abs(a[1]-b[1])<.001 and math.abs(a[2]-b[2])<.001 end
local function rev(L) local r={} local opposite={[0]=1,[1]=0,[2]=3,[3]=2} for i=#L,1,-1 do r[#r+1]={L[i][1],opposite[L[i][2]]} end return r end
function M.plan(bg,sx,sy,tx,ty)
 local a,b={sx,sy},{tx,ty}
 for _,r in pairs(M.actual) do if r.bg==bg and close(a,r.start) and close(b,r.target) then return r.legs end end
 local c=M.catalogs[tostring(bg)] if not c then return nil,"unreviewed_background" end
 local i,j for k,p in ipairs(c.points) do if close(a,p) then i=k end if close(b,p) then j=k end end
 if not i or not j then return nil,"not_precomputed" end
 if i==j then return {} end
 for _,r in ipairs(c.routes) do if r.start==i and r.target==j then return r.legs elseif r.start==j and r.target==i then return rev(r.legs) end end
 return nil,"no_route"
end
-- Do not feed fractional legs into the existing MovePerson: it rounds each leg up to 0.2.
-- This executor caps each frame at the remaining step and never snaps a visible actor to a new endpoint.
function M.walk(pid,L,face)
 local function person() for _,u in ipairs(JY.Smap) do if u[1]==pid then return u end end end
 local w=person() if not w then return false,"actor_not_present" end
 for _,leg in ipairs(L) do
  local remaining,d=leg[1],leg[2]
  while remaining>1e-8 do
   w=person() if not w then return false,"actor_removed" end
   local n=math.min(.2,remaining)
   w[2]=w[2]+CC.DX[d]*n;w[3]=w[3]+CC.DY[d]*n;w[4]=d;w[5]=1
   remaining=remaining-n
   JY.ReFreshTime=lib.GetTime();DrawSMap();lib.GetKey();ReFresh(1.25)
  end
 end
 w=person();w[5]=0;if face then w[4]=face end
