local failed={}
local function pos(pid) for _,u in ipairs(JY.Smap) do if u[1]==pid then return u end end end
local function scope()
 if not JY or not JY.Smap or rawget(_G,"koWujeTownNPC") then return false end
 if rawget(_G,"SnrRoom")==0 then return false end
 if JY.Status==GAME_WMAP or JY.Status==GAME_WARWIN or JY.Status==GAME_WARLOSE then return false end
 return M.masks[tostring(SnrBg())]~=nil
