local function blocked(bg,x,y)
 local row=M.masks[tostring(bg)][math.floor(y+1e-7)+1]
 if not row then return true end
 local xx=math.floor(x+1e-7)
 for k=1,#row,2 do if xx<row[k] then return false elseif xx<=row[k+1] then return true end end
 return false
end
local function point(x,y) return 11+18*x,3+18*y end
local function clear(bg,sx,sy,tx,ty,ax,ay,bx,by,outside)
 local x0,y0=point(sx,sy);local x1,y1=point(tx,ty)
 local n=math.max(1,math.ceil(math.sqrt((x1-x0)^2+(y1-y0)^2)*4))
 local a1,a2,b1,b2
 if ax then a1,a2=point(ax,ay);b1,b2=point(bx,by) end
 for k=0,n do
  local x,y=x0+(x1-x0)*k/n,y0+(y1-y0)*k/n
  if x<0 or x>=640 or y<0 or y>=400 then if not outside then return false end
  elseif blocked(bg,x,y) then
   if not a1 or ((x-a1)^2+(y-a2)^2>64.000001 and (x-b1)^2+(y-b2)^2>64.000001) then return false end
  end
 end
 return true
end
local function legs(sx,sy,tx,ty,first)
 local a=((tx-sx)-2*(ty-sy))/4;local b=((tx-sx)+2*(ty-sy))/4
 local A=math.abs(a)>1e-9 and {math.abs(a),a>0 and 0 or 1}
 local B=math.abs(b)>1e-9 and {math.abs(b),b>0 and 3 or 2}
 local r={}
 if first then if A then r[#r+1]=A end if B then r[#r+1]=B end
 else if B then r[#r+1]=B end if A then r[#r+1]=A end end
 return r
end
local function valid(bg,sx,sy,L,tx,ty,outside)
