 while i>1 do local p=math.floor(i/2);if not smaller(v,h[p]) then break end h[i]=h[p];i=p;h[i]=v end
end
local function pop(h)
 local v=h[1];local last=table.remove(h);if #h==0 then return v end
 local i=1;h[1]=last
 while true do local k=i*2;if k>#h then break end if k<#h and smaller(h[k+1],h[k]) then k=k+1 end
  if not smaller(h[k],last) then break end h[i]=h[k];i=k;h[i]=last
 end
 return v
end
local dynamic={}
local cachedPlan=M.plan
function M.path(bg,sx,sy,tx,ty)
 local key=string.format('%d|%.6f,%.6f|%.6f,%.6f',bg,sx,sy,tx,ty)
 if dynamic[key] then return dynamic[key] end
 if not M.masks[tostring(bg)] then return nil,'unreviewed_background' end
 local L=cachedPlan(bg,sx,sy,tx,ty)
 if L and valid(bg,sx,sy,L,tx,ty,true) then dynamic[key]=L;return L end
 if math.abs(sx-tx)+math.abs(sy-ty)<1e-9 then return {} end
 local spx,spy=point(sx,sy);local tpx,tpy=point(tx,ty)
 local sout=spx<0 or spx>=640 or spy<0 or spy>=400
 local tout=tpx<0 or tpx>=640 or tpy<0 or tpy>=400
 if sout and tout then
  for _,af in ipairs({true,false}) do local p=legs(sx,sy,tx,ty,af)
   if valid(bg,sx,sy,p,tx,ty,true) then dynamic[key]=p;return p end
  end
  return nil,'outside_portal_blocked'
 end
 if sout or tout then
  local D=M.portals[tostring(bg)]
  if not D then return nil,'no_portal' end
  if tout then local R,e=M.path(bg,tx,ty,sx,sy);if not R then return nil,e end;L=reverse(R)
  else
   local pre
   for _,af in ipairs({true,false}) do local p=legs(sx,sy,D[1],D[2],af)
    if valid(bg,sx,sy,p,D[1],D[2],true) then pre=p;break end
   end
   if not pre then return nil,'portal_blocked' end
   local tail,e=M.path(bg,D[1],D[2],tx,ty);if not tail then return nil,e end
   L={} for _,s in ipairs(pre) do L[#L+1]=s end for _,s in ipairs(tail) do L[#L+1]=s end
  end
  dynamic[key]=compact(L);return dynamic[key]
 end
 for _,af in ipairs({true,false}) do L=legs(sx,sy,tx,ty,af)
  if valid(bg,sx,sy,L,tx,ty,false) then dynamic[key]=L;return L end
 end
 local A,B=anchors(bg,sx,sy,true),anchors(bg,tx,ty,false)
 if #A==0 or #B==0 then return nil,#A==0 and 'start_blocked' or 'target_blocked' end
 local tu,tv=(tx+2*ty)/4/.2,(tx-2*ty)/4/.2
 local function heuristic(id) local i,j=nodepos(id) return math.abs(i-tu)+math.abs(j-tv) end
 local goals={} for _,p in ipairs(B) do goals[p.id]=goals[p.id] or {};table.insert(goals[p.id],p) end
 local heap,dist,prev,origin={},{},{},{};local seq=0
 for _,p in ipairs(A) do
  local state=p.id*5+p.dir+1;local old=dist[state]
  if not old or p.cost<old[1]-1e-7 or (math.abs(p.cost-old[1])<1e-7 and p.turn<old[2]) then
   dist[state]={p.cost,p.turn};origin[state]=p.L;seq=seq+1;push(heap,{p.cost+heuristic(p.id),p.turn,seq,p.cost,state})
  end
 end
 local best,bturn,win,tail=math.huge,math.huge,nil,nil
 while #heap>0 do
  local item=pop(heap);local f,t,g,state=item[1],item[2],item[4],item[5]
  if f>best+1e-7 then break end
  local current=dist[state]
  if current and math.abs(current[1]-g)<1e-7 and current[2]==t then
   local id,last=math.floor(state/5),state%5-1
   for _,p in ipairs(goals[id] or {}) do
    local cost,turn=g+p.cost,t+p.turn+((last>=0 and p.dir>=0 and last~=p.dir) and 1 or 0)
    if cost<best-1e-7 or (math.abs(cost-best)<1e-7 and turn<bturn) then best,bturn,win,tail=cost,turn,state,p.L end
   end
   for _,n in ipairs(neighbors(bg,id)) do
    local ns=n[1]*5+n[2]+1;local ng,nt=g+1,t+((last>=0 and last~=n[2]) and 1 or 0);local old=dist[ns]
    if not old or ng<old[1]-1e-7 or (math.abs(ng-old[1])<1e-7 and nt<old[2]) then
     dist[ns]={ng,nt};prev[ns]=state;seq=seq+1;push(heap,{ng+heuristic(n[1]),nt,seq,ng,ns})
    end
   end
  end
 end
 if not win then return nil,'disconnected' end
 local back={};local state=win
 while prev[state] do back[#back+1]={.2,state%5-1};state=prev[state] end
 L={} for _,s in ipairs(origin[state]) do L[#L+1]=s end for i=#back,1,-1 do L[#L+1]=back[i] end for _,s in ipairs(tail) do L[#L+1]=s end
 L=compact(L)
 if not valid(bg,sx,sy,L,tx,ty,false) then return nil,'validation_failed' end
 dynamic[key]=L;return L
end
local logged={}
local function failure(pid,reason,x,y)
 failed[pid]=true
 local key=tostring(SnrBg())..':'..tostring(pid)..':'..tostring(reason)
 if logged[key] then return end;logged[key]=true
 local f=io.open((CONFIG.CurrentPath or './')..'campaign_movement.log','a')
 if f then f:write(key,' event=',tostring(JY.EventID),' target=',tostring(x),',',tostring(y),'\n');f:close() end
end
local function animate(plans)
 local moving=true
 while moving do
  moving=false
  for _,p in ipairs(plans) do
   local u=pos(p.pid);local s=p.L[p.index]
   while s and p.remaining<=1e-8 do p.index=p.index+1;s=p.L[p.index];p.remaining=s and s[1] or 0 end
   if u and s then
    local n=math.min(.2,p.remaining);local d=s[2]
    u[2],u[3],u[4],u[5]=u[2]+DX[d]*n,u[3]+DY[d]*n,d,1
    p.remaining=p.remaining-n;moving=true
   elseif u then u[5]=0 end
  end
  if moving then JY.ReFreshTime=lib.GetTime();DrawSMap();lib.GetKey();ReFresh(1.25) end
 end
 for _,p in ipairs(plans) do local u=pos(p.pid) if u then u[5]=0;if p.face~=nil then u[4]=p.face end end end
 DrawSMap();ShowScreen()
end
local function run(pid,L,face)
 failed[pid]=nil
 animate({{pid=pid,L=L,index=1,remaining=L[1] and L[1][1] or 0,face=face}})
end
function M.install()
 rawset(_G,'koRouteFailed',function(pid) return failed[pid] end)
 rawset(_G,'koCalculatedRoutes',M)
 local oldPlan,oldWalk,oldMove,oldLeave,oldToDoor,oldExit=SnrPlan,SnrWalk,MovePerson,SnrLeave,SnrToDoor,SnrExit
 for b in pairs(M.masks) do
  local id=tonumber(b)
  if rawget(_G,'SnrSeatExit') then SnrSeatExit[id]=nil end
 end
 for b,D in pairs(M.portals) do SnrDoors[tonumber(b)]=D end
 SnrPlan=function(sx,sy,tx,ty,pid)
  if not scope() then return oldPlan(sx,sy,tx,ty,pid) end
  local L,e=M.path(SnrBg(),sx,sy,tx,ty)
  if not L then if pid then failure(pid,e,tx,ty) end;return {},sx,sy end
  if pid then failed[pid]=nil end;return L,tx,ty
 end
 SnrWalk=function(pid,x,y,d)
  if not scope() then return oldWalk(pid,x,y,d) end
  local u=pos(pid);if not u then return false end
  local L,e=M.path(SnrBg(),u[2],u[3],x,y)
  if not L then failure(pid,e,x,y);return true end -- handled: never fall through to AddPerson/teleport
  run(pid,L,d);return true
 end
 MovePerson=function(...)
  if not scope() then return oldMove(...) end
  local args,plans={...},{}
  for i=1,#args,3 do
   local pid,n,d=args[i],args[i+1],args[i+2];local u=pos(pid)
   if u then
    local x,y=u[2]+DX[d]*math.max(0,n),u[3]+DY[d]*math.max(0,n)
    local L,e=M.path(SnrBg(),u[2],u[3],x,y)
    if L then failed[pid]=nil;plans[#plans+1]={pid=pid,L=L,index=1,remaining=L[1] and L[1][1] or 0,face=d}
    else failure(pid,e,x,y) end
   end
  end
  animate(plans)
 end
 local function leave(ids,ax,ay)
  if not scope() then return oldLeave(ids,ax,ay) end
  local D=M.portals[tostring(SnrBg())]
  for _,pid in ipairs(ids) do if pos(pid) then
   SnrWalk(pid,D[1],D[2])
   if not failed[pid] then SnrWalk(pid,D[3],D[4]) end
   if not failed[pid] then DecPerson(pid) end
  end end
  DrawSMap();ShowScreen()
 end
 SnrLeave=leave
 SnrExit=function(pid) if scope() then return leave({pid}) end return oldExit(pid) end
 SnrToDoor=function(ids,ax,ay)
  if not scope() then return oldToDoor(ids,ax,ay) end
  local D=M.portals[tostring(SnrBg())];local ux=D[3]>D[1] and 2 or -2;local uy=D[4]>D[2] and 1 or -1
  local used={}
  for _,u in ipairs(JY.Smap) do local included=false for _,pid in ipairs(ids) do if u[1]==pid then included=true end end;if not included then used[#used+1]={u[2],u[3]} end end
  for i,pid in ipairs(ids) do local u=pos(pid)
   if u then
    local col=#ids>=3 and (i-1)%2 or 0;local chosen
    for row=math.floor((i-1)/2),16 do
     local x,y=D[1]-row*ux+col*ux,D[2]-row*uy-col*uy
     local free=true for _,p in ipairs(used) do if (x-p[1])^2+4*(y-p[2])^2<7.99 then free=false end end
     if free then local L=M.path(SnrBg(),u[2],u[3],x,y);if L then chosen={x,y,L};break end end
    end
    if chosen then run(pid,chosen[3]);used[#used+1]={chosen[1],chosen[2]} else failure(pid,'door_queue_blocked',D[1],D[2]) end
   end
  end
 end
end
return M

end
install_code(M)
return M
